INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-city-heads-command-escort', 'free-city', 10, 'City Head''s Command Escort', '우두머리 지휘 호위조', 'commander', 'command', 4, 'Head''s Seal Room', '우두머리 도장방', 1550, 372, 4, NULL, 10, 95, 44, 42, 40, 70, NULL, NULL, NULL, 34, 82, '["roll-call","shield-line","thin-clad"]', '["government-conscript-spears","arc-house-levy-hooks","government-aid-post-net-teams"]', 'Plated shields, short axes and a carbine each with rounds counted at the bench. The head carries the command sheet; every city that stamped it sends its squads to this one hand.', '쇠판을 댄 방패와 짧은 도끼, 작업대에서 센 탄을 넣은 기병총을 하나씩 갖춘다. 우두머리는 지휘 한 장을 지니고, 그 장에 도장을 찍은 도시들이 모두 이 한 사람에게 분대를 보낸다.', 'Two layers: a fitted synthetic coat over a short work jacket. A green armband over the city''s collar cord; the head wears the city seal on a cord at the neck.', '두 겹이다. 짧은 작업 웃옷 위에 몸에 맞춘 합성 섬유 외투를 입는다. 도시의 깃 끈 위에 초록 완장을 두르고, 우두머리는 도시의 도장을 끈에 꿰어 목에 건다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-contract-commanders-guard', 'free-city', 20, 'Contract Commander''s Guard', '계약 지휘자 호위조', 'commander', 'command', 3, 'Contract Board', '계약 셈판', 760, 220, NULL, NULL, 8, 85, 36, 34, 34, 55, NULL, NULL, NULL, 34, 70, '["hired-company","roll-call"]', '["government-reserve-club-lines","arc-house-levy-cleavers","arc-net-throwing-crews"]', 'Hatchets, short pry bars and pistols. They guard the person a city head has handed the command to by written contract; the contract states the days and the pay.', '손도끼와 짧은 지렛대, 권총을 든다. 우두머리가 계약서로 지휘를 맡긴 사람을 지킨다. 계약서에 날수와 품삯이 적혀 있다.', 'Three layers: a quilted synthetic coat, a padded vest and boots. A green armband and the badge of the bench they come from sewn on the left breast.', '세 겹이다. 합성 섬유 누빔 외투와 솜 조끼, 장화를 입는다. 초록 완장을 두르고 왼쪽 가슴에 제가 속한 대의 표지를 꿰맨다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-guard-share-pole-crews', 'free-city', 30, 'Guard-Share Pole Crews', '지킴 몫 장대조', 'infantry', 'line', 1, 'Watch-Share Hall', '지킴 몫 회관', 190, 50, NULL, NULL, 40, 66, 18, 26, 22, 12, NULL, NULL, NULL, 32, 44, '["charge-breaker"]', '["government-bridge-end-sled-patrols","arc-house-sled-raiders","government-rim-ski-scouts"]', 'Hook poles and pipe spears from the bench racks. These are the days every bench owes its city each year; the hands come because the share is owed, not because they are paid.', '작업대 걸이에서 꺼낸 갈고리 장대와 관 창을 든다. 모든 작업대가 해마다 제 도시에 지는 날수다. 손들은 품삯이 아니라 진 몫 때문에 나온다.', 'Four layers worn mostly in the entrance halls: work clothes, a padded vest, a fur cap and over-boots. A green armband on whatever coat the hand owns.', '주로 대합실에서 지내므로 네 겹이다. 작업복과 솜 조끼, 털모자, 덧신이다. 저마다 가진 겉옷에 초록 완장을 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-contract-shield-company', 'free-city', 40, 'Contract Shield Company', '계약 방패대', 'infantry', 'line', 2, 'Watch-Share Hall', '지킴 몫 회관', 420, 122, NULL, NULL, 36, 72, 24, 40, 26, 45, NULL, NULL, NULL, 30, 56, '["hired-company","shield-line"]', '["government-reserve-riflemen","government-regular-riflemen","arc-house-levy-rifles"]', 'Shields cut from car doors and faced with rubber, and short spears. Hands bought by contract when the guard share runs short; cheap to hire, dear to keep.', '차 문을 잘라 고무를 댄 방패와 짧은 창을 든다. 지킴 몫이 모자랄 때 계약으로 산 손이다. 빌리기는 싸고 오래 두기는 비싸다.', 'Three layers: a quilted synthetic coat over a work vest and boots. A green armband and the contract number chalked on the shield.', '세 겹이다. 작업 조끼 위에 합성 섬유 누빔 외투를 입고 장화를 신는다. 초록 완장을 두르고 방패에 계약 번호를 분필로 적었다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-digging-bench-axe-crews', 'free-city', 50, 'Digging Bench Axe Crews', '굴착대 도끼조', 'infantry', 'shock', 2, 'Watch-Share Hall', '지킴 몫 회관', 480, 120, NULL, NULL, 28, 72, 36, 26, 38, 28, NULL, NULL, NULL, 36, 56, '["tunnel-fighter"]', '["government-conscript-air-rifles","arc-house-crossbow-skirmishers","government-aid-post-litter-bearers"]', 'Splitting axes, short picks and headlamps from the digging benches that cut wells and tunnels. They know the bends of their own section by feel.', '우물과 굴을 뚫는 굴착대의 쪼갬 도끼와 짧은 곡괭이, 머리 등을 갖춘다. 제 구간의 굽이를 손으로 안다.', 'Three layers for the platform levels: layered work clothes with patched knees, a tool belt and a padded cap. A green armband and the digging bench badge on the left breast.', '승강장 층에서 지내므로 세 겹이다. 무릎을 덧댄 겹 작업복과 공구 허리띠, 솜 모자다. 초록 완장을 두르고 왼쪽 가슴에 굴착대 표지를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-contract-storm-company', 'free-city', 60, 'Contract Storm Company', '계약 돌격대', 'infantry', 'shock', 3, 'Contract Board', '계약 셈판', 840, 245, 6, NULL, 24, 88, 44, 30, 52, 55, NULL, NULL, NULL, 33, 66, '["hired-company","plate-biter"]', '["government-regular-riflemen","government-light-mortar-crews","arc-baptised-eye-marksmen"]', 'Heavy hammers and plate-cutting axes, with aprons of riveted sheet. Contract fighters who take the hardest doors; their bodies are their own, without machines.', '묵직한 망치와 쇠판 자르는 도끼를 들고, 리벳 박은 철판 앞치마를 두른다. 가장 단단한 문을 맡는 계약 전투원이다. 몸에 기계를 달지 않았다.', 'Three layers: a fitted synthetic coat cut short over the riveted apron, and boots with steel toes. A green armband and a contract tag on a wire at the collar.', '세 겹이다. 리벳 앞치마 위에 짧게 자른 합성 섬유 외투를 몸에 맞춰 입고, 앞코에 쇠를 댄 장화를 신는다. 초록 완장을 두르고 깃에 철사로 계약 표를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-heads-own-watch', 'free-city', 70, 'Head''s Own Watch', '우두머리 직속 지킴대', 'infantry', 'line', 4, 'Head''s Seal Room', '우두머리 도장방', 1500, 375, 3, NULL, 24, 102, 44, 52, 44, 82, NULL, NULL, NULL, 29, 80, '["shield-line","last-to-leave","thin-clad"]', '["government-watchtower-marksmen","government-heavy-mortar-battery","arc-baptised-eye-marksmen"]', 'Riveted plate shields and short swords ground at the bench, with breast plates cut from old machine casings. The head''s own household and its oldest hands.', '작업대에서 간 짧은 칼과 리벳 박은 쇠 방패를 들고, 옛 기계 껍데기를 잘라 만든 흉갑을 입는다. 우두머리 집안 사람과 가장 오래 된 손들이다.', 'Two layers: a fitted synthetic coat and a short jacket, little patched. A green armband over the city''s collar cord.', '두 겹이다. 몸에 맞춘 합성 섬유 외투와 짧은 웃옷이고, 기운 자리가 적다. 도시의 깃 끈 위에 초록 완장을 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-station-air-rifle-guards', 'free-city', 80, 'Station Air-Rifle Guards', '역 공기총 지킴조', 'missile', 'skirmish', 1, 'Watch-Share Hall', '지킴 몫 회관', 200, 50, NULL, NULL, 24, 64, 12, 14, 18, 10, 12, 90, 24, 34, 46, '["muscle-powered","quiet-step","tunnel-fighter"]', '["government-conscript-pick-squads","arc-house-levy-cleavers","government-reserve-club-lines"]', 'Air rifles made at the bench from old compressors and pressure bottles, filled by hand pump, firing steel shot or lead pellets. No primer, no powder, little sound and no smoke.', '옛 압축기와 고압 통으로 작업대에서 만든 공기총을 손 펌프로 채워 쇠구슬이나 납알을 쏜다. 뇌관도 화약도 들지 않고, 소리가 작고 연기가 없다.', 'Three layers for the platform levels: work clothes, a padded vest and a cap. A green armband and the station''s number painted on the pump.', '승강장 층에서 지내므로 세 겹이다. 작업복과 솜 조끼, 모자다. 초록 완장을 두르고 펌프에 역 번호를 칠했다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-rail-spike-throwers', 'free-city', 90, 'Rail-Spike Throwers', '철정 투척조', 'missile', 'anti-armour', 1, 'Watch-Share Hall', '지킴 몫 회관', 230, 58, NULL, NULL, 16, 70, 18, 18, 24, 20, 110, 70, 5, 34, 48, '["muscle-powered","machine-hunter"]', '["government-exit-breaking-squad","arc-house-exit-breakers"]', 'Throwing bars and sharpened rail spikes, and hooks for prising plates off a trolley. Anyone who has worked the track can throw them.', '던지는 쇠막대와 벼린 철정, 수레의 판을 뜯는 갈고리를 든다. 선로 일을 해 본 사람이면 누구나 던진다.', 'Four layers: work clothes, a padded vest, over-boots and a fur cap. A green armband and leather pads on the throwing arm.', '네 겹이다. 작업복과 솜 조끼, 덧신, 털모자다. 초록 완장을 두르고 던지는 팔에 가죽 덧대를 댔다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-brass-counting-riflemen', 'free-city', 100, 'Brass-Counting Riflemen', '탄피 세는 소총반', 'missile', 'rifle', 2, 'Watch-Share Hall', '지킴 몫 회관', 530, 156, NULL, 'ammo', 28, 68, 16, 17, 22, 22, 22, 150, 14, 33, 56, '["hired-company","hand-loaded"]', '["government-conscript-spears","government-district-bayonet-line","arc-house-shield-bearers","government-pole-charge-hunters"]', 'Bolt-action rifles mended at the bench and rounds reloaded by hand into picked-up brass. A squad that fails to pick up its cases gets fewer rounds in the next contract.', '작업대에서 고친 볼트식 소총과 주운 탄피에 손으로 다시 채운 탄을 쓴다. 쏜 탄피를 줍지 못한 분대는 다음 계약에서 탄을 덜 받는다.', 'Four layers: a long windproof synthetic coat, a face cover, snow goggles and over-boots, for firing on the ground. A green armband and a case bag on the hip.', '지상에서 쏘므로 네 겹이다. 합성 섬유 바람막이 긴 외투와 얼굴 가리개, 눈가리개, 덧신이다. 초록 완장을 두르고 허리에 탄피 자루를 찬다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-passage-marksmen', 'free-city', 110, 'Passage Marksmen', '통로 저격조', 'missile', 'marksman', 3, 'Contract Board', '계약 셈판', 1000, 250, 5, 'ammo', 12, 66, 18, 20, 22, 20, 85, 200, 10, 33, 66, '["skilled-crew","quiet-step"]', '["government-district-command-escort","government-assembly-members-sworn-retinue","arc-baptised-duel-escort","arc-baptised-plate-breakers"]', 'Scoped rifles with barrels re-cut at the bench and the best of the hand-loaded rounds. They shoot along the open tunnel stretches where no one lives.', '작업대에서 총열을 다시 깎은 조준경 소총과 손으로 채운 탄 가운데 가장 좋은 것을 쓴다. 사람이 살지 않는 트인 터널 구간을 따라 쏜다.', 'Three layers: a fitted synthetic coat, a padded hood and soft boots. A green armband turned inside out until the shot.', '세 겹이다. 몸에 맞춘 합성 섬유 외투와 솜 두건, 무른 장화다. 초록 완장은 쏠 때까지 뒤집어 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-bench-mortar-crews', 'free-city', 120, 'Bench Mortar Crews', '작업대 박격포조', 'missile', 'artillery', 3, 'Contract Board', '계약 셈판', 1100, 275, 3, 'ammo', 12, 68, 14, 14, 20, 15, 140, 400, 8, 28, 64, '["skilled-crew","hand-loaded"]', '["government-conscript-spears","arc-house-levy-hooks","government-checkpoint-shield-line"]', 'Mortar tubes turned at the bench and bombs refilled with black powder. Big guns are rare in the Free Cities: the benches can cut a barrel but cannot feed it.', '작업대에서 깎은 박격포 포신과 검은 화약을 다시 채운 포탄을 쓴다. 자유도시들에 큰 포는 드물다. 작업대는 포신을 깎을 수 있지만 먹일 탄이 없다.', 'Three layers: a quilted synthetic coat, thick gloves and over-boots. A green armband and soot on the sleeves from the black powder.', '세 겹이다. 합성 섬유 누빔 외투와 두꺼운 장갑, 덧신이다. 초록 완장을 두르고, 소매에 검은 화약 그을음이 묻어 있다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-rail-trolley-raiders', 'free-city', 130, 'Rail Trolley Raiders', '궤도 수레 습격대', 'fast', 'raider', 2, 'Track Shed', '궤도 정비고', 520, 130, NULL, NULL, 16, 105, 30, 20, 28, 22, NULL, NULL, NULL, 72, 56, '["rail-borne","quiet-step"]', '["government-light-mortar-crews","government-aid-post-litter-bearers","arc-field-mechanics"]', 'Hand trolleys rowed by lever along the rails, carrying hatchets, hook poles and a bag of caltrops. They hit the rear of a line and are gone before the stamp for pursuit arrives.', '손잡이를 저어 레일 위를 가는 손수레차에 손도끼와 갈고리 장대, 마름쇠 자루를 싣는다. 대열 뒤를 치고, 쫓으라는 도장이 오기 전에 사라진다.', 'Three layers for the tunnels: work clothes, a padded vest and gloves with leather palms for the lever. A green armband.', '터널에서 지내므로 세 겹이다. 작업복과 솜 조끼, 손잡이를 쥐는 가죽 바닥 장갑이다. 초록 완장을 두른다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-edge-sled-scouts', 'free-city', 140, 'Edge Sled Scouts', '경계 썰매 정찰조', 'fast', 'recon', 2, 'Track Shed', '궤도 정비고', 450, 112, NULL, NULL, 10, 92, 22, 18, 22, 15, NULL, NULL, NULL, 80, 54, '["frost-hardened","scout-deploy"]', '["government-capital-defence-scout-drones","government-watchtower-marksmen","arc-house-crossbow-skirmishers"]', 'Light sleds with sails for the flat snow, short spears and field glasses. They watch the crossings and the Arc land border; they turn back before the machine rim.', '평평한 눈 위를 가는 돛 단 가벼운 썰매와 짧은 창, 쌍안경을 갖춘다. 건널목과 아크와의 땅 경계를 지켜보고, 기계 테두리 앞에서 돌아선다.', 'Six layers: work clothes, over-trousers, a long windproof coat, a face cover, snow goggles and over-boots. A green armband and white snow over-suits on the river side.', '여섯 겹이다. 작업복과 덧바지, 바람막이 긴 외투, 얼굴 가리개, 눈가리개, 덧신이다. 초록 완장을 두르고, 강 쪽에서는 흰 눈 덧옷을 입는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-flywheel-trolley-shock-crews', 'free-city', 150, 'Flywheel Trolley Shock Crews', '관성 수레 돌격조', 'fast', 'shock', 2, 'Track Shed', '궤도 정비고', 640, 160, NULL, NULL, 14, 125, 34, 24, 38, 38, NULL, NULL, NULL, 66, 58, '["rail-borne","tunnel-fighter"]', '["government-regular-riflemen","arc-house-levy-rifles","government-aid-post-net-teams"]', 'Plated rail trolleys driven by a heavy flywheel spun up by hand before the charge, with a ram plate in front. No battery to freeze, but they go only where the rails go.', '돌격 전에 손으로 돌려 둔 무거운 관성 바퀴로 가는 철판 레일 수레로, 앞에 들이받는 판을 달았다. 얼 전지가 없지만 레일이 있는 곳만 간다.', 'Two layers behind the plates: a short synthetic jacket and leather gloves. A green band painted along the ram plate.', '철판 뒤에 서므로 두 겹이다. 짧은 합성 섬유 웃옷과 가죽 장갑이다. 들이받는 판을 따라 초록 띠를 칠했다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-fibre-scout-drones', 'free-city', 160, 'Fibre Scout Drones', '줄 정찰 드론조', 'drone', 'recon', 2, 'Bench Assembly Floor', '작업대 조립장', 560, 140, 4, 'cells,parts', 6, 54, 10, 6, 18, 0, NULL, NULL, NULL, 78, 56, '["fibre-guided","scout-deploy"]', '["government-heavy-mortar-battery","government-watchtower-marksmen","arc-baptised-eye-marksmen"]', 'Six small drones that pay out fibre drawn from old tunnel cable, so jamming cannot touch them. A cut line is hard to join again, so each flight costs a spool.', '옛 터널 케이블에서 뽑은 광섬유를 풀며 나는 작은 드론 여섯 대라 전파 방해가 듣지 않는다. 끊긴 줄은 다시 잇기 어려워 한 번 날 때마다 줄 한 감개가 든다.', 'Operators wear three layers: work clothes, a padded vest and fingerless gloves. A green armband and spools hung on the belt.', '조종수는 세 겹이다. 작업복과 솜 조끼, 손가락 없는 장갑이다. 초록 완장을 두르고 허리에 줄 감개를 건다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-wire-guided-rail-strikers', 'free-city', 170, 'Wire-Guided Rail Strikers', '줄 레일 타격조', 'drone', 'strike', 2, 'Bench Assembly Floor', '작업대 조립장', 620, 155, 4, 'cells,parts', 4, 60, 10, 8, 18, 10, 120, 240, 1, 62, 56, '["fibre-guided"]', '["government-armoured-carrier-section","arc-revived-armoured-locomotive","government-field-gun-battery"]', 'Four small rail carts steered by wire along the track, each with a charge in front. Made to meet armour in the tunnels, where radio does not reach.', '줄로 부려 레일 위를 구르는 작은 수레 넷으로, 앞에 폭약을 하나씩 실었다. 전파가 닿지 않는 터널에서 장갑을 맞으려 만든 것이다.', 'Operators wear three layers for the tunnels and kneel behind a plated shield. A green armband and a wire reel strapped to the chest.', '조종수는 터널에서 지내므로 세 겹이고, 철판 방패 뒤에 무릎을 꿇는다. 초록 완장을 두르고 가슴에 줄 감개를 묶는다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-bench-drop-drones', 'free-city', 180, 'Bench Drop Drones', '작업대 투하 드론조', 'drone', 'strike', 3, 'Airframe Bench', '기체 작업대', 1000, 250, 4, 'cells,parts', 6, 60, 10, 6, 18, 0, 120, 400, 2, 85, 62, '["radio-linked","skilled-crew"]', '["government-armoured-gun-carriage","government-light-mortar-crews","government-district-command-escort"]', 'Radio-flown drones that drop small charges and come back. They fly only on days when the wind is under ten metres a second, and the batteries are kept in warmed boxes until launch.', '작은 폭약을 떨어뜨리고 돌아오는 전파 조종 드론이다. 바람이 초속 10미터 아래인 날에만 날고, 전지는 띄우기 전까지 데운 상자에 둔다.', 'Operators wear four layers on the ground: a windproof coat, a face cover, snow goggles and gloves. A green armband and the airframe bench badge.', '조종수는 지상에서 네 겹이다. 바람막이 외투와 얼굴 가리개, 눈가리개, 장갑이다. 초록 완장과 기체 작업대 표지를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-relay-strike-flight', 'free-city', 190, 'Relay Strike Flight', '중계 타격 편대', 'drone', 'strike', 4, 'Radio Bench', '전파 작업대', 1750, 420, 2, 'cells,parts', 8, 70, 12, 8, 20, 5, 190, 450, 3, 82, 78, '["radio-linked","skilled-crew","thin-clad"]', '["government-depot-revived-tank","arc-near-house-heads-guard","government-heavy-mortar-battery"]', 'A flight of eight drones passing commands through a relay drone, with charges for armour. Losing one is a circuit board no one can make again.', '중계 드론 하나를 거쳐 명령을 받는 드론 여덟 대의 편대로, 장갑을 노리는 폭약을 단다. 한 대를 잃는 것은 누구도 다시 만들지 못하는 회로판 하나를 잃는 일이다.', 'Operators wear two layers in a covered post: a short synthetic jacket and thin gloves. A green armband and the radio bench badge.', '조종수는 덮인 자리에서 두 겹이다. 짧은 합성 섬유 웃옷과 얇은 장갑이다. 초록 완장과 전파 작업대 표지를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-armoured-battery-trolley', 'free-city', 200, 'Armoured Battery Trolley', '장갑 전지 수레', 'war-machine', 'armour', 3, 'Armoured Trolley Yard', '장갑 수레 차고', 1000, 250, 4, 'cells,parts', 2, 4200, 26, 14, 260, 70, NULL, NULL, NULL, 36, 64, '["rail-borne","iron-dread"]', '["government-checkpoint-shield-line","government-reserve-riflemen","arc-house-levy-hooks","arc-baptised-strong-arm-squad"]', 'Battery rail trolleys from the Sinjeong and Guro depots, plated and fitted with a ram. The cold halves what the batteries give, so they are charged at the windmills just before they go.', '신정과 구로 차량기지의 전지 수레에 쇠판과 들이받는 판을 달았다. 추위가 전지를 반으로 줄이므로 나가기 직전에 바람틀에서 채운다.', 'Plates welded from different hulls, each a different grey, with a green band. The crew rides inside in work clothes.', '서로 다른 차체에서 떼어 용접한 판이라 판마다 회색이 다르고, 초록 띠를 칠했다. 조원은 작업복 차림으로 안에 탄다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-armoured-gun-trolley', 'free-city', 210, 'Armoured Gun Trolley', '포 실은 장갑 수레', 'war-machine', 'armour', 4, 'Armoured Trolley Yard', '장갑 수레 차고', 1900, 475, 2, 'ammo,cells', 2, 5600, 18, 10, 250, 95, 220, 300, 14, 30, 78, '["rail-borne","skilled-crew","thin-clad"]', '["government-guard-hall-shield-line","arc-baptised-near-house-guard","government-district-command-escort"]', 'A battery trolley carrying one gun behind plate. This is as heavy as Free City armour goes: there are shells for only a few battles a year.', '쇠판 뒤에 포 한 문을 실은 전지 수레다. 자유도시 장갑은 여기서 멈춘다. 한 해에 몇 번 싸울 포탄밖에 없다.', 'Grey plate with the green band and the depot''s mark, patched where shot has struck. The crew wears short jackets and leather gloves.', '회색 판에 초록 띠와 차량기지 표를 칠했고, 탄을 맞은 자리를 기웠다. 조원은 짧은 웃옷과 가죽 장갑을 낀다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-crew-net-teams', 'free-city', 220, 'Crew Net Teams', '작업조 그물반', 'support', 'countermeasure', 1, 'Crew Muster Room', '작업조 모임방', 240, 60, NULL, NULL, 12, 62, 12, 14, 18, 18, NULL, NULL, NULL, 33, 48, '["net-casting","quiet-step"]', '["government-capital-defence-scout-drones","government-capital-defence-strike-drones"]', 'Throwing nets and the exit-shaft nets the crew mends every week. Nets are the cheapest and steadiest guard against drones there is.', '던지는 그물과 작업조가 주마다 손질하는 출입구 굴 그물을 맡는다. 그물은 드론을 막는 가장 싸고 꾸준한 방법이다.', 'Four layers: work clothes, a padded vest, a fur cap and over-boots. A green armband and net needles stuck in the cap.', '네 겹이다. 작업복과 솜 조끼, 털모자, 덧신이다. 초록 완장을 두르고 모자에 그물바늘을 꽂았다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-gate-opening-crews', 'free-city', 230, 'Gate-Opening Crews', '출입구 여는 작업조', 'support', 'breacher', 3, 'Bench Master''s Shop', '대주 작업장', 800, 200, NULL, NULL, 12, 76, 24, 22, 34, 40, NULL, NULL, NULL, 32, 64, '["breach-charge","machine-hunter","tunnel-fighter"]', '["government-depot-revived-tank","arc-revived-armoured-locomotive","government-armoured-carrier-section"]', 'Cutting torches, shaped charges and the tools to stop a station''s fans and seal its exits. They would rather make a station unbearable than kill the people in it.', '절단 불꽃과 모양 폭약, 역의 팬을 세우고 출입구를 막는 연장을 갖춘다. 사람을 죽이기보다 역을 견디지 못하게 하는 쪽을 고른다.', 'Three layers: a quilted synthetic coat, a leather apron scorched by the torch and goggles. A green armband and the bench master''s badge.', '세 겹이다. 합성 섬유 누빔 외투와 불꽃에 그을린 가죽 앞치마, 보안경이다. 초록 완장과 대주의 표지를 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-field-repair-crews', 'free-city', 240, 'Field Repair Crews', '현장 수리 작업조', 'support', 'engineer', 3, 'Bench Master''s Shop', '대주 작업장', 740, 185, NULL, NULL, 12, 68, 14, 18, 20, 25, NULL, NULL, NULL, 34, 62, '["field-repair","tunnel-fighter"]', '["government-capital-defence-scout-drones","government-armoured-carrier-section"]', 'Tool rolls, spare motors and parts boxes counted against the contract. They mend drones and trolleys during the fight, and they are the hands the Government borrows for its bridges.', '공구 두루마리와 예비 모터, 계약 앞으로 센 부품 상자를 든다. 싸우는 동안 드론과 수레를 고친다. 정부가 다리를 고칠 때 빌려 가는 손이 이들이다.', 'Three layers for the tunnels: work clothes with tool loops, a padded vest and a headlamp. A green armband and several bench badges on one breast.', '터널에서 지내므로 세 겹이다. 공구 고리를 단 작업복과 솜 조끼, 머리 등이다. 초록 완장을 두르고 한쪽 가슴에 대 표지를 여럿 단다.', NULL);
INSERT INTO wiki_unit (id, faction_id, sort, name, name_ko, category, role, tier, recruit_building, recruit_building_ko, cost, upkeep, unit_cap, scarce_input, squad_size, hp, melee_attack, melee_defence, weapon_strength, armour, missile_damage, range, ammo, speed, leadership, attributes, counters, equipment, equipment_ko, appearance, appearance_ko, gdd_ref) VALUES ('free-city-jamming-teams', 'free-city', 250, 'Jamming Teams', '전파 방해반', 'support', 'countermeasure', 4, 'Radio Bench', '전파 작업대', 1400, 330, 2, NULL, 10, 64, 12, 14, 18, 20, NULL, NULL, NULL, 32, 76, '["static-veil","quiet-step","thin-clad"]', '["government-capital-defence-scout-drones","free-city-bench-drop-drones","government-field-gun-battery"]', 'Jamming sets that cover a station''s ground with noise, drawing a few hundred watts, the heat of several people. They are switched on only when a drone is seen or a fight begins.', '역 하나 둘레의 지상을 잡음으로 덮는 방해기로, 몇백 와트를 먹는다. 사람 몇 명의 난방 몫이다. 드론이 보이거나 싸움이 날 때만 켠다.', 'Two layers: a short synthetic jacket and thin gloves for the dials. A green armband and the radio bench badge.', '두 겹이다. 짧은 합성 섬유 웃옷과 다이얼을 돌리는 얇은 장갑이다. 초록 완장과 전파 작업대 표지를 단다.', NULL);
